alter table public.criterion_scores add constraint criterion_scores_applicability_check CHECK ((applicability = ANY (ARRAY['scored'::text, 'not_observed'::text, 'not_applicable'::text])));
alter table public.criterion_scores add constraint criterion_scores_score_state_check CHECK ((((applicability = 'scored'::text) AND ((score >= 1) AND (score <= 10))) OR ((applicability = ANY (ARRAY['not_observed'::text, 'not_applicable'::text])) AND (score IS NULL))));
alter table public.criterion_scores add constraint criterion_scores_scored_requires_score CHECK (((applicability <> 'scored'::text) OR (score IS NOT NULL)));
alter table public.matches add constraint matches_away_score_check CHECK ((away_score >= 0));
alter table public.matches add constraint matches_check CHECK (((home_club_id IS NULL) OR (away_club_id IS NULL) OR (home_club_id <> away_club_id)));
alter table public.matches add constraint matches_home_score_check CHECK ((home_score >= 0));
alter table public.matches add constraint matches_match_status_check CHECK ((match_status = ANY (ARRAY['scheduled'::text, 'completed'::text, 'cancelled'::text])));
alter table public.observations add constraint observations_evaluation_check CHECK ((evaluation = ANY (ARRAY['positive'::text, 'negative'::text, 'uncertain'::text])));
alter table public.observations add constraint observations_evidence_level_check CHECK ((evidence_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text])));
alter table public.observations add constraint observations_match_clock_nonnegative_check CHECK (((match_clock_seconds IS NULL) OR (match_clock_seconds >= 0)));
alter table public.observations add constraint observations_minute_check CHECK (((minute >= 0) AND (minute <= 150)));
alter table public.observations add constraint observations_period_code_check CHECK (((period_code IS NULL) OR (period_code = ANY (ARRAY['first_half'::text, 'second_half'::text, 'extra_time_first_half'::text, 'extra_time_second_half'::text, 'penalty_shootout'::text, 'unknown'::text]))));
alter table public.observations add constraint observations_session_context_check CHECK ((((session_id IS NOT NULL) AND (rubric_version_id IS NOT NULL)) OR ((session_id IS NULL) AND (session_video_id IS NULL) AND (rubric_version_id IS NULL) AND (criterion_id IS NULL) AND (video_offset_seconds IS NULL) AND (match_clock_seconds IS NULL) AND (period_code IS NULL))));
alter table public.observations add constraint observations_video_offset_nonnegative_check CHECK (((video_offset_seconds IS NULL) OR (video_offset_seconds >= 0)));
alter table public.observations add constraint observations_video_offset_source_check CHECK (((video_offset_seconds IS NULL) OR (session_video_id IS NOT NULL)));
alter table public.player_matches add constraint player_matches_minutes_played_check CHECK (((minutes_played >= 0) AND (minutes_played <= 150)));
alter table public.players add constraint players_height_cm_check CHECK (((height_cm >= 100) AND (height_cm <= 250)));
alter table public.players add constraint players_preferred_foot_check CHECK ((preferred_foot = ANY (ARRAY['left'::text, 'right'::text, 'both'::text])));
alter table public.players add constraint players_profile_status_check CHECK ((profile_status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])));
alter table public.rubric_categories add constraint rubric_categories_category_weight_percent_check CHECK (((category_weight_percent >= 1) AND (category_weight_percent <= 100)));
alter table public.rubric_criteria add constraint rubric_criteria_score_anchors_check CHECK (((jsonb_typeof(score_anchors) = 'object'::text) AND (score_anchors ? '1–2'::text) AND (score_anchors ? '3–4'::text) AND (score_anchors ? '5–6'::text) AND (score_anchors ? '7–8'::text) AND (score_anchors ? '9'::text) AND (score_anchors ? '10'::text)));
alter table public.rubric_criteria add constraint rubric_criteria_weight_percent_check CHECK (((weight_percent >= 1) AND (weight_percent <= 100)));
alter table public.rubric_versions add constraint rubric_versions_score_max_check CHECK ((score_max = 10));
alter table public.rubric_versions add constraint rubric_versions_score_min_check CHECK ((score_min = 1));
alter table public.rubric_versions add constraint rubric_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pilot'::text, 'active'::text, 'retired'::text])));
alter table public.scout_reports add constraint scout_reports_evidence_grade_check CHECK ((evidence_grade = ANY (ARRAY['A'::text, 'B'::text, 'C'::text])));
alter table public.scout_reports add constraint scout_reports_general_rating_check CHECK (((general_rating >= (1)::numeric) AND (general_rating <= (10)::numeric)));
alter table public.scout_reports add constraint scout_reports_report_status_check CHECK ((report_status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'archived'::text])));
alter table public.scouting_sessions add constraint scouting_sessions_completed_time_check CHECK (((completed_at IS NULL) OR (started_at IS NULL) OR (completed_at >= started_at)));
alter table public.scouting_sessions add constraint scouting_sessions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'in_review'::text, 'completed'::text, 'locked'::text])));
alter table public.user_roles add constraint user_roles_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'editor'::text])));
alter table public.video_access_checks add constraint video_access_checks_access_result_check CHECK ((access_result = ANY (ARRAY['available'::text, 'unavailable'::text, 'restricted'::text, 'unknown'::text])));
alter table public.video_access_checks add constraint video_access_checks_account_requirement_check CHECK ((account_requirement = ANY (ARRAY['none'::text, 'free_account'::text, 'subscription'::text, 'institutional'::text, 'unknown'::text])));
alter table public.video_access_checks add constraint video_access_checks_country_code_check CHECK (((country_code)::text ~ '^[A-Z]{2}$'::text));
alter table public.video_access_checks add constraint video_access_checks_coverage_status_check CHECK ((coverage_status = ANY (ARRAY['full_match'::text, 'partial'::text, 'highlights'::text, 'unknown'::text])));
alter table public.video_access_checks add constraint video_access_checks_price_status_check CHECK ((price_status = ANY (ARRAY['free'::text, 'paid'::text, 'unknown'::text])));
alter table public.video_rights_assessments add constraint video_rights_assessments_basis_type_check CHECK ((basis_type = ANY (ARRAY['written_permission'::text, 'contract'::text, 'provider_terms'::text, 'open_license'::text, 'legal_review'::text, 'unknown'::text])));
alter table public.video_rights_assessments add constraint video_rights_assessments_right_type_check CHECK ((right_type = ANY (ARRAY['manual_scouting'::text, 'automated_analysis'::text, 'commercial_use'::text, 'download_storage'::text, 'clip_extraction'::text, 'redistribution'::text])));
alter table public.video_rights_assessments add constraint video_rights_assessments_status_check CHECK ((status = ANY (ARRAY['granted'::text, 'prohibited'::text, 'unknown'::text, 'not_reviewed'::text])));
alter table public.video_rights_assessments add constraint video_rights_assessments_territory_scope_check CHECK ((territory_scope = ANY (ARRAY['global'::text, 'country'::text, 'unknown'::text])));
alter table public.video_rights_assessments add constraint video_rights_country_code_format CHECK (((country_code IS NULL) OR ((country_code)::text ~ '^[A-Z]{2}$'::text)));
alter table public.video_rights_assessments add constraint video_rights_country_scope_consistency CHECK ((((territory_scope = 'country'::text) AND (country_code IS NOT NULL)) OR ((territory_scope <> 'country'::text) AND (country_code IS NULL))));
alter table public.video_rights_assessments add constraint video_rights_granted_requires_evidence CHECK (((status <> 'granted'::text) OR ((basis_type <> 'unknown'::text) AND ((NULLIF(btrim(evidence_url), ''::text) IS NOT NULL) OR (NULLIF(btrim(evidence_note), ''::text) IS NOT NULL)))));
alter table public.video_rights_assessments add constraint video_rights_validity_window CHECK (((valid_until IS NULL) OR (valid_from IS NULL) OR (valid_until >= valid_from)));
alter table public.video_sources add constraint video_sources_discovery_method_check CHECK ((discovery_method = ANY (ARRAY['manual'::text, 'permitted_api'::text, 'partner_feed'::text, 'other'::text])));
alter table public.video_sources add constraint video_sources_officiality_status_check CHECK ((officiality_status = ANY (ARRAY['official'::text, 'third_party_index'::text, 'unknown'::text])));
alter table public.video_sources add constraint video_sources_review_status_check CHECK ((review_status = ANY (ARRAY['candidate'::text, 'reviewed'::text, 'inactive'::text])));
alter table public.video_sources add constraint video_sources_source_key_format CHECK ((source_key ~ '^[a-z0-9][a-z0-9-]{1,62}$'::text));
alter table public.video_sources add constraint video_sources_source_type_check CHECK ((source_type = ANY (ARRAY['official_archive'::text, 'official_channel'::text, 'discovery_index'::text, 'licensed_provider'::text, 'research_dataset'::text, 'other'::text])));
alter table public.videos add constraint videos_access_status_check CHECK ((access_status = ANY (ARRAY['available'::text, 'unavailable'::text, 'restricted'::text, 'unknown'::text])));
alter table public.videos add constraint videos_rights_status_check CHECK ((rights_status = ANY (ARRAY['link_only'::text, 'permission_granted'::text, 'unknown'::text])));
alter table public.videos add constraint videos_video_type_check CHECK ((video_type = ANY (ARRAY['full_match'::text, 'highlights'::text, 'extended_highlights'::text, 'other'::text])));
alter table public.criterion_scores add constraint criterion_scores_criterion_version_fk FOREIGN KEY (criterion_id, rubric_version_id) REFERENCES rubric_criteria(id, rubric_version_id) ON DELETE RESTRICT;
